head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > highlightSelectedWeek]<br/>Calendar 컴포넌트에서 선택된 날짜가 속한 주(Week)에 CSS 를 적용할지 설정합니다.",
    "validation" : [
        "미설정 시 기본값 'false' 로 동작하여 주(Week) 단위 CSS 클래스가 적용되지 않으며, 개별 날짜 셀의 선택 상태만 표시됩니다.",
        "true 설정 시 선택된 날짜가 속한 주(Week)의 7개 셀 전체에 'w2calendar_selected_week' CSS 클래스가 추가됩니다.",
        "true 설정 시 년/월을 탐색할 때도 주(Week) 단위로 CSS 클래스가 적용됩니다.",
        "false (기본값) 설정 시 주(Week) 단위 CSS 클래스가 적용되지 않으며, 개별 날짜 셀의 선택 상태만 표시됩니다.",
        "weekStartsOn 속성에 따라 주(Week)의 요일 매핑이 달라지므로 CSS 클래스가 적용되는 주간의 시작 요일이 변경됩니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        highlightSelectedWeek : con_highlightSelectedWeek.getText(),
        weekStartsOn : con_weekStartsOn.getText()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);

    // 초기 선택일을 2025-05-18 (일요일) 로 고정 — weekStartsOn 변경 시 같은 주 일자 범위 비교 용도
    target1.gotoCalendar("20250518");
}



// 선택된 주(Week) 의 'w2calendar_selected_week' CSS 클래스 적용 셀 개수 / 날짜 목록 확인
scwin.getSelectedWeekInfo = function () {
    let calendarRender = target1.render;
    let selectedWeekCells = calendarRender.querySelectorAll('.w2calendar_selected_week');

    // validation: true 설정 시 7개 셀, false / 미설정 시 0개 셀
    wf_body_bottom.getObj("scwin").setReturnValue("[선택된 주 셀 개수] 'w2calendar_selected_week' 적용 셀 = " + selectedWeekCells.length + "개");

    // validation: 7개 셀의 textContent (weekStartsOn 에 따라 표시 순서/범위 변경)
    let dates = [];
    selectedWeekCells.forEach((el) => { dates.push(el.textContent); });
    wf_body_bottom.getObj("scwin").setReturnValue("[선택된 주 셀 날짜 목록] [" + dates.join(',') + "]");
}



// 개별 선택 셀 (w2calendar_selected) 의 날짜 확인 — true/false 모두 표시되어야 함
scwin.getSelectedCellInfo = function () {
    let calendarRender = target1.render;
    let selectedCells = calendarRender.querySelectorAll('.w2calendar_selected');

    // validation: 개별 날짜 셀의 선택 상태는 highlightSelectedWeek 값에 관계없이 항상 표시됨
    let dates = [];
    selectedCells.forEach((el) => { dates.push(el.textContent); });
    wf_body_bottom.getObj("scwin").setReturnValue("[선택된 셀(개별)] 'w2calendar_selected' 셀 = " + selectedCells.length + "개, 날짜 = [" + dates.join(',') + "]");
}



// 년/월 탐색 후에도 선택된 주(Week) 단위 CSS 클래스가 적용되는지 확인
scwin.btn_navigateNextMonth_onclick = function (e) {
    let calendarRender = target1.render;
    let nextMonthBtn = calendarRender.querySelector('.w2calendar_header_next_month');
    if (nextMonthBtn) {
        nextMonthBtn.click();
        setTimeout(() => {
            // validation: true 설정 시 년/월 탐색 후에도 주(Week) 단위 CSS 클래스가 적용됨
            wf_body_bottom.getObj("scwin").setReturnValue("== 다음 달 탐색 후 ==");
            scwin.getSelectedWeekInfo();
            scwin.getSelectedCellInfo();
        }, 100);
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("[다음 달 버튼] 'w2calendar_header_next_month' 셀 없음");
    }
}



scwin.btn_getInfo_onclick = function (e) {
    scwin.getSelectedWeekInfo();
    scwin.getSelectedCellInfo();
}



scwin.target1_onclick = function (e) {
    setTimeout(() => {
        scwin.getSelectedWeekInfo();
        scwin.getSelectedCellInfo();
    }, 100);
}
